\label{lem:radial}
Assume $(H)$, let $0\le a<b\le\infty$, and let $V\in C^1((a,b))$ be such that $r\mapsto r^{N-1}\varphi_p(V'(r))$ belongs to $C^1((a,b))$, where $\varphi_p(s)=|s|^{p-2}s$. Then $W(x):=V(H_0(x))$ satisfies $\mathcal A(\nabla W(x))=\varphi_p(V'(r))\,\frac{x}{r}$ and
\[
\Delta_p^HW(x)=r^{1-N}\big(r^{N-1}\varphi_p(V'(r))\big)'\Big|_{r=H_0(x)}
\]
pointwise in $\{a<H_0<b\}$, and also in the weak sense there.

\label{lem:key}
Assume that $(H)$ and $(B)$ hold with $p\ge2$. Let $u$ be a weak solution of $-\Delta_B^Hu=g(u)$ that is stable outside a closed set $K$. Let $a,b\in C^1(\mathcal O)$ satisfy the following conditions:
\begin{enumerate}[label=(\roman*)]
\item $a'$ and $b'$ are bounded on $\mathcal O$, $b\ge0$, and $|a(t)|+b(t)\le C(1+|t|)$ for $t\in\mathcal O$;
\item $b'$ has constant sign and does not vanish on $\mathcal O$;
\item there are $\mu,\nu>0$ with $\lambda\mu<\nu$ such that, for $t\in\mathcal O$,
\[
a'(t)^2=\mu|b'(t)|\qquad\text{and}\qquad |g(t)|\,b(t)\le\nu^{-1}g'(t)a(t)^2 .
\]
\end{enumerate}
Put $\Phi:=a^2+b^2|b'|^{-1}$ and $\Psi:=|a|^p|a'|^{2-p}+b^p|b'|^{1-p}$. Then there is $C>0$, depending only on $p,\gamma,\Gamma,\kappa,\delta,M,M_1,\mu$, and $\nu-\lambda\mu$, such that
\begin{equation}\label{eq:key}
\begin{aligned}
\int_{\mathbb{R}^N}g'(u)a(u)^2\psi^p+\int_{\mathbb{R}^N}B'(H(\nabla u))H(\nabla u)|b'(u)|\psi^p\\
\le C\int_{\Omega_1}\Phi(u)\psi^{p-2}|\nabla\psi|^2+C\int_{\Omega_2}\Psi(u)|\nabla\psi|^p
\end{aligned}
\end{equation}
for every nonnegative $\psi\in C^1_c(\mathbb{R}^N\setminus K)$.

\label{prop:est_sing}
Assume that $(H)$ and $(B)$ hold with $p\ge2$, let $q>0$, and let $u$ be a weak solution of \eqref{eq:sing} that is stable outside a closed set $K$. Assume $\alpha_0<1-p$ and let $\alpha\in(\alpha_0,1-p]$. Then
\begin{equation}\label{eq:est_sing}
\int_{\mathbb{R}^N}\Big(B'(H(\nabla u))H(\nabla u)u^{\alpha-1}+u^{\alpha-q}\Big)\eta^{pm}
\le C\int_{\Omega_1}|\nabla\eta|^{\frac{2(q-\alpha)}{q+1}}+C\int_{\Omega_2}|\nabla\eta|^{\frac{p(q-\alpha)}{q+p-1}}
\end{equation}
for every $\eta\in C^1_c(\mathbb{R}^N\setminus K)$ with $0\le\eta\le1$ and every
\begin{equation}\label{eq:m_sing}
m\ge\max\Big\{\frac{q-\alpha}{q+p-1},\ \frac{2(q-\alpha)}{p(q+1)}\Big\},
\end{equation}
with $C$ depending on $m$ but not on $\eta$. When $p=2$ and $\alpha=-1$, the first term on the left must be omitted.

\label{prop:est_exp}
Assume that $(H)$ and $(B)$ hold with $p\ge2$, and let $u$ be a weak solution of \eqref{eq:exp} that is stable outside a closed set $K$. Let $\alpha\in(0,\frac4\lambda)$. Then
\begin{equation}\label{eq:est_exp}
\int_{\mathbb{R}^N}\Big(B'(H(\nabla u))H(\nabla u)e^{\alpha u}+e^{(\alpha+1)u}\Big)\eta^{pm}
\le C\int_{\Omega_1}|\nabla\eta|^{2(\alpha+1)}+C\int_{\Omega_2}|\nabla\eta|^{p(\alpha+1)}
\end{equation}
for every $\eta\in C^1_c(\mathbb{R}^N\setminus K)$ with $0\le\eta\le1$ and every $m\ge\alpha+1$, with $C$ depending on $m$ but not on $\eta$.

\label{cor:stable}
Assume that $(H)$ and $(B)$ hold with $p\ge2$.
\begin{enumerate}[label=(\alph*)]
\item Let $q>0$ and assume that
\begin{equation}\label{eq:cond_sing}
\alpha_0<1-p\qquad\text{and}\qquad N<\frac{p(q-\alpha_0)}{q+p-1},
\end{equation}
and, if $\kappa>0$, also $N<\frac{2(q-\alpha_0)}{q+1}$. Then \eqref{eq:sing} has no stable weak solution.
\item If $2\le N<\frac{p(p+3)}{p-1}$ and $q>q_*(N,p)$, then $\Delta_p^Hu=u^{-q}$ has no stable weak solution. Indeed, for $\Delta_p^H$ and $2\le N<\frac{p(p+3)}{p-1}$, condition \eqref{eq:cond_sing} is equivalent to $q>q_*(N,p)$.
\item If $N<p(1+\frac4\lambda)$ and, when $\kappa>0$, also $N<2(1+\frac4\lambda)$, then \eqref{eq:exp} has no stable weak solution. For $\Delta_p^H$ this condition reads $N<\frac{p(p+3)}{p-1}$.
\end{enumerate}

\label{lem:z}
Let $p\ge2$, $q>0$, and $N\ge2$, and assume that
\begin{equation}\label{eq:zcond}
N-(q+1)\tau>0\qquad\text{and}\qquad D:=\big[N-(q-1)\tau\big]^2-\frac{4p}{p-1}(N-q\tau)\ge0 .
\end{equation}
Let $a>0$, and let $v$ be the solution of $(r^{N-1}\varphi_p(v'))'=r^{N-1}v^{-q}$ on $(0,\infty)$ with $v(0)=a$ and $v'(0)=0$. Then $z(r):=\tau v(r)-rv'(r)>0$ for all $r\ge0$, and $v(r)>c_sr^\tau$ for all $r>0$.
